function loadComponent(e,o,t){const n=document.getElementById(e);if(!n)return;const r=window.location.pathname;let i=r.replace(/\/$/,"");const c=(i.match(/\//g)||[]).length;let s="";c>1&&(s="../".repeat(c-1));const a=s+o,l=t?s+t:null;fetch(a).then(e=>{if(!e.ok)throw new Error(`HTTP ${e.status}`);return e.text()}).then(e=>{if(n.innerHTML=e,l){const t=document.createElement("script");t.src=l,t.defer=!0,document.body.appendChild(t)}}).catch(t=>{console.error(`Error loading ${e}:`,t),console.error(`Attempted path: ${a}`)})}loadComponent("header","./components/layout/header/header.html","./components/layout/header/header.min.js"),loadComponent("footer","./components/layout/footer/footer.html");